// Drives the exact stdio command OpenClaw registered (mcp.servers.gbrain) with real MCP JSON-RPC.
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
const cfg = JSON.parse(readFileSync(process.env.OPENCLAW_CONFIG_PATH, 'utf8')).mcp.servers.gbrain;
const p = spawn(cfg.command, cfg.args, { env: { ...process.env, ...cfg.env }, stdio: ['pipe', 'pipe', 'inherit'] });
let buf = '', id = 0; const waiters = new Map();
p.stdout.on('data', (d) => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; const m = JSON.parse(line); if (m.id && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } });
const rpc = (method, params) => new Promise((res) => { const myId = ++id; waiters.set(myId, res); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: myId, method, params }) + '\n'); });
const call = async (name, args) => { const r = await rpc('tools/call', { name, arguments: args }); return r.error ?? JSON.parse(r.result.content[0].text); };
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tools = await rpc('tools/list', {});
console.log('tools:', tools.result.tools.map((t) => t.name).join(', '));
const mode = process.argv[2];
if (mode === 'remember') {
  const r = await call('remember', { fact: process.argv[3], entity: 'gbrain-install-check', provenance: 'install-check', content_origin: 'inferred' });
  console.log('remember:', r.status, r.status_text ?? '', 'id=', r.id ?? r.fact_id);
} else if (mode === 'recall') {
  const r = await call('recall', { entity: 'gbrain-install-check' });
  console.log('recall:', JSON.stringify((r.facts ?? []).map((f) => ({ id: f.fact_id ?? f.id, fact: f.fact, provenance: f.provenance }))));
} else if (mode === 'forget') {
  for (const fid of process.argv.slice(3)) { const r = await call('forget', { fact_id: fid, reason: 'install-check cleanup' }); console.log('forget', fid, JSON.stringify(r).slice(0, 200)); }
}
p.stdin.end(); p.kill();
process.exit(0);

